/** @param {NS} ns */
export async function main(ns) {
  const targets = new Set();
  function scan(srv) {
    const neighbors = ns.scan(srv);
    for (const n of neighbors) {
      if (!targets.has(n)) {
        targets.add(n);
        scan(n);
      }
    }
  }
  scan('home');

  let best = null;
  let bestMoney = 0;
  const myLevel = ns.getHackingLevel();

  for (const srv of targets) {
    if (srv === 'home') continue;
    const maxMoney = ns.getServerMaxMoney(srv);
    const reqLevel = ns.getServerRequiredHackingLevel(srv);
    if (reqLevel <= myLevel && maxMoney > bestMoney) {
      bestMoney = maxMoney;
      best = srv;
    }
  }

  if (!best) best = 'n00dles';

  ns.tprint(`Target: ${best} with max money $${bestMoney}`);

  while (true) {
    const sec = ns.getServerSecurityLevel(best);
    const minSec = ns.getServerMinSecurityLevel(best);
    const money = ns.getServerMoneyAvailable(best);
    const maxMoney = ns.getServerMaxMoney(best);

    if (sec > minSec + 5) {
      await ns.weaken(best);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(best);
    } else {
      await ns.hack(best);
    }
  }
}

